/**
 * Differential test support for packed logical rules: the selected packed plan must evaluate to the same bag as the
 * unoptimized algebra over the same in-memory data, and the encoded rule program can be inspected for the alternatives
 * it generated.
 */
final class PackedPlanDifferentialSupport {

	static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	static final String PREFIXES = "PREFIX : <urn:t:>\nPREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n";

	/** Unbound statement patterns are expensive; a pattern whose subject is bound by the prefix is a point lookup. */
	static final PackedCostModel SUBJECT_LOOKUP_COSTS = new PackedCostModel() {
		@Override
		public double estimateRows(PackedQueryView query, int relationId) {
			return query.isStatementPattern(relationId) ? 10_000.0d : Double.NaN;
		}

		@Override
		public void estimate(PackedQueryView query, int relationId, PackedCostContext context,
				PackedCostEstimate output) {
			if (!query.isStatementPattern(relationId)) {
				return;
			}
			if (context.prefixRelationCount() != 0 && (query.prefixBindsStatementComponent(context, relationId, 0)
					|| query.prefixBindsStatementComponent(context, relationId, 2))) {
				output.setContextualRows(1.0d, 1.0d);
			} else {
				output.setRows(10_000.0d, 10_000.0d);
			}
		}
	};

	/**
	 * {@link #SUBJECT_LOOKUP_COSTS} plus a refinement that lets a typed anti-join own its probe cost at a nominal
	 * price, so that whenever the MINUS -> correlated NOT EXISTS rewrite is generated the anti-join wins the plan. A
	 * differential test that uses this model therefore exercises the rewrite itself rather than the canonical MINUS
	 * (which the plain cost model prefers for bodies containing a nested MINUS).
	 */
	static final PackedCostModel ANTI_JOIN_FORCING_COSTS = new PackedCostModel() {
		@Override
		public double estimateRows(PackedQueryView query, int relationId) {
			return SUBJECT_LOOKUP_COSTS.estimateRows(query, relationId);
		}

		@Override
		public void estimate(PackedQueryView query, int relationId, PackedCostContext context,
				PackedCostEstimate output) {
			SUBJECT_LOOKUP_COSTS.estimate(query, relationId, context, output);
		}

		@Override
		public void refineOperator(PackedQueryView query, int relationId, PackedCostContext context,
				PackedCostEstimate output) {
			if (!Double.isFinite(context.leftInputRows()) || !query.isAntiJoin(relationId)) {
				return;
			}
			output.setRows(context.leftInputRows(), output.workRows());
			output.setLocalPhysicalCost(5.0d, 0.0d, 1.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
			output.setDependentSubqueriesCosted(true);
		}
	};

	private PackedPlanDifferentialSupport() {
	}

	/**
	 * Plans {@code query} with {@code costs}, evaluates both the unoptimized algebra and the selected plan over
	 * {@code data} and asserts the bags agree. Returns the selected plan so callers can additionally assert that the
	 * rewrite under test was (or was not) taken, which keeps a differential test from passing vacuously.
	 */
	static TupleExpr assertPackedPlanPreservesResults(Model data, String query, PackedCostModel costs,
			PackedPredicateRangeProvider provider, List<String> expected) {
		TupleExpr original = parse(query);
		List<String> reference = evaluate(data, original);
		PackedQuery packed = PackedQueryCodec.encodeForPlanning(original.clone(), provider);
		long generated = generatedRuleMask(packed);
		TupleExpr selected = PackedCascadesPlanner
				.optimize(original.clone(), OptimizationGoal.root(original, null), costs, provider)
				.selectedPlan();
		List<String> actual = evaluate(data, selected);
		if (expected != null) {
			List<String> sortedExpected = new ArrayList<>(expected);
			Collections.sort(sortedExpected);
			assertEquals(sortedExpected, reference, "reference oracle disagrees with hand-computed bag");
		}
		assertEquals(reference, actual, "selected packed plan changed the result bag (generatedRuleMask=0x"
				+ Long.toHexString(generated) + ")\n" + selected);
		return selected;
	}

	/**
	 * True when the plan contains a FILTER whose condition is {@code NOT EXISTS} (the correlated MINUS rewrite or a
	 * typed anti-join materialized from it) or that carries the {@code minus-assured-shared} semantic hint.
	 */
	static boolean containsNotExistsFilter(TupleExpr plan) {
		boolean[] found = new boolean[1];
		plan.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Filter filter) {
				if (filter.getCondition()instanceof Not not && not.getArg() instanceof Exists
						|| "minus-assured-shared".equals(filter.getStringMetricPlanned("optimizer.semiAntiKind"))) {
					found[0] = true;
				}
				super.meet(filter);
			}
		});
		return found[0];
	}

	static long generatedRuleMask(PackedQuery packed) {
		long generated = 0L;
		for (int relationId = 1; relationId <= packed.relationCount(); relationId++) {
			generated |= packed.relRuleMask(relationId);
		}
		return generated;
	}

	static boolean generates(TupleExpr expression, long ruleMask) {
		return (generatedRuleMask(PackedQueryCodec.encodeForPlanning(expression.clone())) & ruleMask) != 0L;
	}

	static TupleExpr parse(String query) {
		return new SPARQLParser().parseQuery(PREFIXES + query, "urn:t:").getTupleExpr();
	}

	static List<String> evaluate(Model data, TupleExpr expression) {
		TripleSource source = new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate,
					Value object, Resource... contexts) {
				return new CloseableIteratorIteration<>(data.getStatements(subject, predicate, object, contexts)
						.iterator());
			}

			@Override
			public ValueFactory getValueFactory() {
				return VF;
			}
		};
		QueryRoot root = expression instanceof QueryRoot queryRoot ? queryRoot.clone()
				: new QueryRoot(expression.clone());
		List<String> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> result = new StrictEvaluationStrategy(source, null).precompile(root)
				.evaluate(EmptyBindingSet.getInstance())) {
			while (result.hasNext()) {
				BindingSet bindings = result.next();
				TreeMap<String, String> sorted = new TreeMap<>();
				for (String name : bindings.getBindingNames()) {
					Value value = bindings.getValue(name);
					if (value != null) {
						sorted.put(name, value.toString());
					}
				}
				StringBuilder builder = new StringBuilder();
				sorted.forEach((name, value) -> {
					if (builder.length() > 0) {
						builder.append('|');
					}
					builder.append(name).append('=').append(value);
				});
				rows.add(builder.toString());
			}
		}
		Collections.sort(rows);
		return rows;
	}

	static Model model() {
		return new LinkedHashModel();
	}

	static void add(Model model, String subject, String predicate, Value object) {
		model.add(VF.createIRI("urn:t:" + subject), VF.createIRI("urn:t:" + predicate), object);
	}

	static IRI iri(String localName) {
		return VF.createIRI("urn:t:" + localName);
	}
}
